import {
	ChangeDetectionStrategy,
	Component,
	Input,
	effect,
} from '@angular/core';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { LucideAngularModule } from 'lucide-angular';

import { TranslationService } from '../../../core/services/translation.service';

interface ServiceStage {
	key: string;
	icon: string;
	order: number;
}


@Component({
	selector: 'app-service-stages',
	standalone: true,
	imports: [
		CommonModule,
		TranslateModule,
		LucideAngularModule,
	],
	templateUrl: './service-stages.component.html',
	styleUrl: './service-stages.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ServiceStagesComponent {
	@Input() consultationLink = '';

	@Input() sectionKey = 'SERVICESTAGES.BRANDING';

readonly stages: ServiceStage[] = [
	{
		key: 'ONE',
		icon: 'compass',
		order: 1,
	},
	{
		key: 'TWO',
		icon: 'target',
		order: 2,
	},
	{
		key: 'THREE',
		icon: 'pen-tool',
		order: 3,
	},
];

	constructor(
		public translationService: TranslationService
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}
}