import {
	AfterViewInit,
	ChangeDetectionStrategy,
	Component,
	ElementRef,
	Inject,
	Input,
	PLATFORM_ID,
	QueryList,
	ViewChildren,
	effect,
} from '@angular/core';

import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';

interface TitlePart {
	text: string;
	style?: 'medium' | 'light' | 'barcely';
	break?: boolean;
}

@Component({
	selector: 'app-service-audit',
	standalone: true,
	imports: [CommonModule, RouterModule, TranslateModule],
	templateUrl: './service-audit.component.html',
	styleUrl: './service-audit.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ServiceAuditComponent implements AfterViewInit {
	@Input() sectionKey = 'SERVICEAUDIT.BRANDING';
	@Input() consultationLink = '/contact';

	@ViewChildren('revealText')
	revealTexts!: QueryList<ElementRef<HTMLElement>>;

	constructor(
		@Inject(DOCUMENT) private document: Document,
		@Inject(PLATFORM_ID) private platformId: Object,
		public translationService: TranslationService,
		private translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	getTitleParts(): TitlePart[] {
		const parts = this.translate.instant(this.sectionKey + '.TITLE_PARTS');

		return Array.isArray(parts) ? parts : [];
	}

	getDescriptions(): string[] {
		const list = this.translate.instant(this.sectionKey + '.DESCRIPTIONS');

		return Array.isArray(list) ? list : [];
	}

	async ngAfterViewInit(): Promise<void> {
		// SSR protection
		if (!isPlatformBrowser(this.platformId)) {
			return;
		}

		gsap.registerPlugin(ScrollTrigger);

		// Load SplitText only in browser
		const { SplitText } = await import('gsap/SplitText');

		gsap.registerPlugin(SplitText);

		this.revealTexts.forEach((textElement) => {
			const element = textElement.nativeElement;

			const split = new SplitText(element, {
				type: 'words',
			});

			// Initial state
			gsap.set(split.words, {
				opacity: 0.1,
			});

			// Reveal on scroll
			gsap.to(split.words, {
				opacity: 1,
				stagger: 0.05,
				ease: 'none',

				scrollTrigger: {
					trigger: element,
					start: 'top 80%',
					toggleActions: 'play none none none',
				},
			});
		});
	}
}
